import sys

class Stack:
    def __init__(self):
        self.items = []

    def push(self, value):
        self.items.append(value)

    def pop(self):
        if self.is_empty():
            return None
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            return None
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def print_contents(self):
        if self.is_empty():
            return "Stack is empty."
        return "Stack contents: [" + ", ".join(str(item) for item in self.items) + "]"


def main():
    stack = Stack()

    for line in sys.stdin:
        line = line.strip()

        if line.startswith("push"):
            parts = line.split(" ", 1)
            if len(parts) >= 2:
                value = parts[1]
                stack.push(value)
        elif line == "pop":
            if stack.is_empty():
                print("Stack is empty.")
            else:
                value = stack.pop()
                print("Popped value: " + str(value))
        elif line == "peek":
            if stack.is_empty():
                print("Stack is empty.")
            else:
                print("Top of the stack: " + str(stack.peek()))
        elif line == "print":
            print(stack.print_contents())
        elif line.startswith("exit"):
            break


if __name__ == "__main__":
    main()
